<template>
  <el-dialog
    v-model="visible"
    :title="isEdit ? t('notifier.templates.editTitle') : t('notifier.templates.createTitle')"
    width="780px"
    :close-on-click-modal="false"
    @closed="onClosed"
  >
    <el-form ref="formRef" :model="form" :rules="rules" label-width="110px">
      <el-form-item :label="t('notifier.templates.templateName')" prop="name">
        <el-input v-model="form.name" :placeholder="t('notifier.templates.templateNamePlaceholder')" />
      </el-form-item>
      <el-form-item :label="t('notifier.templates.eventType')" prop="event_type">
        <el-select v-model="form.event_type" :placeholder="t('notifier.templates.eventTypePlaceholder')" style="width: 100%">
          <el-option :label="t('notifier.templates.eventAlertFiring')" value="alert.firing" />
          <el-option :label="t('notifier.templates.eventAlertResolved')" value="alert.resolved" />
          <el-option :label="t('notifier.templates.eventIncidentCreated')" value="incident.created" />
          <el-option :label="t('notifier.templates.eventIncidentResolved')" value="incident.resolved" />
        </el-select>
      </el-form-item>
      <el-form-item :label="t('notifier.templates.channelType')" prop="channel_type">
        <el-radio-group v-model="form.channel_type">
          <el-radio value="email">{{ t('notifier.templates.email') }}</el-radio>
          <el-radio value="webhook">Webhook</el-radio>
        </el-radio-group>
      </el-form-item>
      <el-form-item :label="t('notifier.templates.subjectTemplate')" prop="subject_template">
        <el-input v-model="form.subject_template" :placeholder="t('notifier.templates.subjectPlaceholder')" />
      </el-form-item>
      <el-form-item :label="t('notifier.templates.bodyTemplate')" prop="body_template">
        <CodeEditor v-model="form.body_template" :rows="10" :placeholder="t('notifier.templates.bodyPlaceholder')" />
      </el-form-item>
      <el-form-item :label="t('common.format')" prop="format">
        <el-radio-group v-model="form.format">
          <el-radio value="text">{{ t('notifier.templates.formatText') }}</el-radio>
          <el-radio value="markdown">Markdown</el-radio>
          <el-radio value="html">HTML</el-radio>
        </el-radio-group>
      </el-form-item>
    </el-form>

    <template #footer>
      <el-button @click="visible = false">{{ t('common.cancel') }}</el-button>
      <el-button type="primary" :loading="submitting" @click="onSubmit">
        {{ isEdit ? t('common.save') : t('common.create') }}
      </el-button>
    </template>
  </el-dialog>
</template>

<script setup lang="ts">
import { ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import {
  createNotificationTemplate,
  updateNotificationTemplate,
  type NotificationTemplateCreate,
  type NotificationTemplateEventType,
  type NotificationTemplateFormat,
  type NotificationTemplateRead,
} from '@/api/notificationTemplates'
import CodeEditor from '@/components/common/CodeEditor.vue'
import { showError } from '@/utils/error'

const { t } = useI18n()

const props = defineProps<{
  modelValue: boolean
  template?: NotificationTemplateRead | null
}>()

const emit = defineEmits<{
  'update:modelValue': [value: boolean]
  success: []
}>()

const visible = ref(props.modelValue)
const submitting = ref(false)
const formRef = ref<FormInstance>()
const isEdit = ref(false)

const form = ref<{
  name: string
  event_type: NotificationTemplateEventType
  channel_type: 'email' | 'webhook'
  subject_template: string
  body_template: string
  format: NotificationTemplateFormat
}>({
  name: '',
  event_type: 'alert.firing',
  channel_type: 'email',
  subject_template: '',
  body_template: '',
  format: 'markdown',
})

const rules: FormRules = {
  name: [{ required: true, message: () => t('notifier.templates.nameRequired'), trigger: 'blur' }],
  event_type: [{ required: true, message: () => t('notifier.templates.eventTypeRequired'), trigger: 'change' }],
  channel_type: [{ required: true, message: () => t('notifier.templates.channelTypeRequired'), trigger: 'change' }],
  body_template: [{ required: true, message: () => t('notifier.templates.bodyRequired'), trigger: 'blur' }],
  format: [{ required: true, message: () => t('notifier.templates.formatRequired'), trigger: 'change' }],
}

watch(
  () => props.modelValue,
  (val) => {
    visible.value = val
  }
)

watch(
  () => props.template,
  (template) => {
    if (template) {
      isEdit.value = true
      form.value = {
        name: template.name,
        event_type: template.event_type,
        channel_type: template.channel_type,
        subject_template: template.subject_template || '',
        body_template: template.body_template,
        format: template.format,
      }
    } else {
      isEdit.value = false
      resetForm()
    }
  },
  { immediate: true }
)

function resetForm() {
  form.value = {
    name: '',
    event_type: 'alert.firing',
    channel_type: 'email',
    subject_template: '',
    body_template: '',
    format: 'markdown',
  }
}

function onClosed() {
  emit('update:modelValue', false)
  formRef.value?.resetFields()
  resetForm()
}

async function onSubmit() {
  const valid = await formRef.value?.validate().catch(() => false)
  if (!valid) return

  submitting.value = true
  try {
    const data: NotificationTemplateCreate = {
      name: form.value.name,
      event_type: form.value.event_type,
      channel_type: form.value.channel_type,
      subject_template: form.value.subject_template || undefined,
      body_template: form.value.body_template,
      format: form.value.format,
    }
    if (props.template) {
      await updateNotificationTemplate(props.template.id, data)
    } else {
      await createNotificationTemplate(data)
    }
    ElMessage.success(isEdit.value ? t('notifier.templateUpdated') : t('notifier.templateCreated'))
    emit('success')
    visible.value = false
  } catch (error) {
    showError(error, isEdit.value ? t('notifier.updateTemplateFailed') : t('notifier.createTemplateFailed'))
  } finally {
    submitting.value = false
  }
}
</script>
