<template>
  <div class="page-template-list">
    <CrudToolbar :title="t('notifier.templatesTitle')" :can-create="authStore.isAdmin" @create="onCreate" />

    <el-card>
      <DataTable
        v-model:current-page="page"
        v-model:page-size="pageSize"
        :data="templates"
        :loading="loading"
        :server-side="true"
        :total="total"
      >
        <el-table-column prop="event_type" :label="t('notifier.templates.eventType')" width="150" />
        <el-table-column prop="channel_type" :label="t('notifier.templates.channelType')" width="110" />
        <el-table-column prop="name" :label="t('common.name')" min-width="180" />
        <el-table-column prop="format" :label="t('common.format')" width="100" />
        <el-table-column prop="is_default" :label="t('common.default')" width="90">
          <template #default="{ row }">
            <el-tag v-if="row.is_default" type="info" size="small">{{ t('common.default') }}</el-tag>
            <span v-else>-</span>
          </template>
        </el-table-column>
        <el-table-column :label="t('common.actions')" width="260" fixed="right">
          <template #default="{ row }">
            <el-button link type="primary" size="small" @click="onPreview(row)">
              {{ t('common.preview') }}
            </el-button>
            <el-button
              v-if="authStore.isAdmin && !row.is_default"
              link
              type="primary"
              size="small"
              @click="onEdit(row)"
            >
              {{ t('common.edit') }}
            </el-button>
            <ConfirmButton
              v-if="authStore.isAdmin && !row.is_default"
              :title="t('notifier.confirmDeleteTemplate')"
              confirm-button-type="danger"
              @confirm="onDelete(row)"
            >
              <el-button link type="danger" size="small">{{ t('common.delete') }}</el-button>
            </ConfirmButton>
          </template>
        </el-table-column>
      </DataTable>
    </el-card>

    <NotificationTemplateFormDialog
      v-model="dialogVisible"
      :template="selectedTemplate"
      @success="loadTemplates"
    />

    <el-dialog v-model="previewVisible" :title="t('notifier.templates.previewTitle')" width="680px">
      <p><strong>{{ t('notifier.templates.subjectColon') }}</strong>{{ previewResult?.subject || '-' }}</p>
      <CodeEditor
        v-model="previewBody"
        :rows="12"
        disabled
      />
      <template #footer>
        <el-button @click="previewVisible = false">{{ t('common.close') }}</el-button>
      </template>
    </el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage } from 'element-plus'
import { useAuthStore } from '@/stores/auth'
import {
  deleteNotificationTemplate,
  getNotificationTemplates,
  previewNotificationTemplate,
  type NotificationTemplateRead,
  type PreviewTemplateResponse,
} from '@/api/notificationTemplates'
import { useListQuery } from '@/composables/useListQuery'
import ConfirmButton from '@/components/common/ConfirmButton.vue'
import NotificationTemplateFormDialog from './NotificationTemplateFormDialog.vue'
import CodeEditor from '@/components/common/CodeEditor.vue'
import DataTable from '@/components/common/DataTable.vue'
import CrudToolbar from '@/components/common/CrudToolbar.vue'
import { showError } from '@/utils/error'

const { t } = useI18n()
const authStore = useAuthStore()

const templates = ref<NotificationTemplateRead[]>([])
const total = ref(0)
const loading = ref(false)
const dialogVisible = ref(false)
const selectedTemplate = ref<NotificationTemplateRead | null>(null)
const previewVisible = ref(false)
const previewResult = ref<PreviewTemplateResponse | null>(null)

const { page, pageSize } = useListQuery({
  defaults: {},
  parse: () => ({}),
  serialize: () => ({}),
})

const previewBody = computed({
  get: () => previewResult.value?.body || '',
  set: () => {},
})

async function loadTemplates() {
  loading.value = true
  try {
    const response = await getNotificationTemplates({
      page: page.value,
      page_size: pageSize.value,
    })
    templates.value = response.items
    total.value = response.total
  } catch (error) {
    showError(error, t('notifier.loadTemplatesFailed'))
  } finally {
    loading.value = false
  }
}

function onCreate() {
  selectedTemplate.value = null
  dialogVisible.value = true
}

function onEdit(row: NotificationTemplateRead) {
  selectedTemplate.value = row
  dialogVisible.value = true
}

async function onPreview(row: NotificationTemplateRead) {
  try {
    previewResult.value = await previewNotificationTemplate(row.id, {
      context: {
        alert: { rule_name: t('notifier.previewSample.ruleName'), severity: 'critical' },
        incident: { id: 1, title: t('notifier.previewSample.incidentTitle') },
        node: { node_id: 'node-1', name: t('notifier.previewSample.nodeName') },
      },
    })
    previewVisible.value = true
  } catch (error) {
    showError(error, t('notifier.previewFailed'))
  }
}

async function onDelete(row: NotificationTemplateRead) {
  if (row.is_default) {
    ElMessage.warning(t('notifier.defaultTemplateNoDelete'))
    return
  }
  try {
    await deleteNotificationTemplate(row.id)
    ElMessage.success(t('notifier.templateDeleted'))
    loadTemplates()
  } catch (error) {
    showError(error, t('common.deleteFailed'))
  }
}

watch(
  () => ({ page: page.value, pageSize: pageSize.value }),
  loadTemplates,
  { deep: true, immediate: true }
)
</script>
