import apiClient from './client'
import type { Page, PageParams } from './page'

export type NotificationTemplateFormat = 'text' | 'markdown' | 'html'
export type NotificationTemplateEventType =
  | 'alert.firing'
  | 'alert.resolved'
  | 'incident.created'
  | 'incident.resolved'
export type NotificationTemplateChannelType = 'email' | 'webhook'

export interface NotificationTemplateRead {
  id: number
  name: string
  event_type: NotificationTemplateEventType
  channel_type: NotificationTemplateChannelType
  subject_template?: string | null
  body_template: string
  format: NotificationTemplateFormat
  is_default: boolean
  created_at: string
  updated_at: string
}

export interface NotificationTemplateCreate {
  name: string
  event_type: NotificationTemplateEventType
  channel_type: NotificationTemplateChannelType
  subject_template?: string
  body_template: string
  format?: NotificationTemplateFormat
}

export interface NotificationTemplateUpdate {
  name?: string
  subject_template?: string
  body_template?: string
  format?: NotificationTemplateFormat
}

export interface PreviewTemplateRequest {
  context?: Record<string, unknown>
}

export interface PreviewTemplateResponse {
  subject?: string | null
  body: string
  format: NotificationTemplateFormat
}

export interface NotificationTemplateListParams extends PageParams {
  event_type?: NotificationTemplateEventType
  channel_type?: NotificationTemplateChannelType
}

export async function getNotificationTemplates(
  params?: NotificationTemplateListParams
): Promise<Page<NotificationTemplateRead>> {
  const response = await apiClient.get<Page<NotificationTemplateRead>>('/v1/notification-templates', {
    params,
  })
  return response.data
}

export async function createNotificationTemplate(
  data: NotificationTemplateCreate
): Promise<NotificationTemplateRead> {
  const response = await apiClient.post<NotificationTemplateRead>('/v1/notification-templates', data)
  return response.data
}

export async function getNotificationTemplate(
  templateId: number
): Promise<NotificationTemplateRead> {
  const response = await apiClient.get<NotificationTemplateRead>(
    `/v1/notification-templates/${templateId}`
  )
  return response.data
}

export async function updateNotificationTemplate(
  templateId: number,
  data: NotificationTemplateUpdate
): Promise<NotificationTemplateRead> {
  const response = await apiClient.put<NotificationTemplateRead>(
    `/v1/notification-templates/${templateId}`,
    data
  )
  return response.data
}

export async function deleteNotificationTemplate(templateId: number): Promise<void> {
  await apiClient.delete(`/v1/notification-templates/${templateId}`)
}

export async function previewNotificationTemplate(
  templateId: number,
  data?: PreviewTemplateRequest
): Promise<PreviewTemplateResponse> {
  const response = await apiClient.post<PreviewTemplateResponse>(
    `/v1/notification-templates/${templateId}/preview`,
    data || {}
  )
  return response.data
}
